import { Container, Matrix } from 'pixi.js';
import type { AssetPack, SwfGlowFilter as GlowOptions } from '../assets/asset-pack';
import { SwfClip } from '../assets/swf-clip';
import { MAIN_MENU, type MainMenuMotion } from '../core/main-menu';
import { SwfSymbolView, type RasterTextures } from './swf-symbol-view';
import { SwfGlowFilter } from './swf-glow-filter';

/** Menu display objects retain independent child timelines, including the title's stop(179). */
export class MainMenuView {
  readonly root = new Container();
  private title: SwfSymbolView;
  private titlePose: SwfClip;
  private controls;
  private background: SwfSymbolView;
  private glow: SwfGlowFilter;
  constructor(pack: AssetPack, textures: RasterTextures) {
    this.background = new SwfSymbolView(MAIN_MENU.background, pack, textures);
    this.background.update(1);
    this.root.addChild(this.background.root);
    this.controls = MAIN_MENU.controls.map((piece) => {
      const view = new SwfSymbolView(piece.symbol, pack, textures),
        pose = new SwfClip(piece.symbol, pack),
        wrapper = new Container();
      wrapper.addChild(view.root);
      this.root.addChild(wrapper);
      pose.advance(1);
      return { piece, view, pose, wrapper };
    });
    this.glow = new SwfGlowFilter(this.glowOptions(0));
    this.controls[0].wrapper.filters = [this.glow];
    this.title = new SwfSymbolView(MAIN_MENU.title.symbol, pack, textures);
    this.titlePose = new SwfClip(MAIN_MENU.title.symbol, pack);
    const m = MAIN_MENU.title.matrix;
    this.title.root.setFromMatrix(new Matrix(m.a, m.b, m.c, m.d, m.tx / 20, m.ty / 20));
    this.root.addChild(this.title.root);
  }
  private glowOptions(strength: number): GlowOptions {
    return {
      kind: 'glow',
      color: [255, 255, 255, 255],
      blurX: 7,
      blurY: 7,
      strength,
      passes: 3,
      inner: false,
      knockout: false,
      compositeSource: true,
    };
  }
  hover(name: string, over: boolean) {
    const control = this.controls.find((c) => c.piece.name === name);
    const inner = [...(control?.pose.children.values() ?? [])].find(
      (c) => c.placement.name === 'inner',
    );
    if (over) inner?.clip.gotoAndPlay(2);
    else inner?.clip.gotoAndStop(1);
  }
  update(motion: MainMenuMotion) {
    for (const { piece, view, pose, wrapper } of this.controls) {
      const m = piece.matrix;
      wrapper.setFromMatrix(
        new Matrix(
          m.a,
          m.b,
          m.c,
          m.d,
          motion.parked ? -100 : m.tx / 20,
          motion.parked ? -100 : m.ty / 20,
        ),
      );
      pose.advance(motion.age + 1);
      view.setParentAlpha(motion.controlAlpha);
      view.updatePose(pose);
    }
    this.glow.setOptions(this.glowOptions(motion.glowStrength));
    this.titlePose.advance(motion.age + 1);
    this.title.setParentAlpha(motion.titleAlpha);
    this.title.updatePose(this.titlePose);
  }
  get titleFrame() {
    return this.titlePose.children.get(1)?.clip.frame;
  }
  destroy() {
    this.background.destroy();
    this.title.destroy();
    for (const control of this.controls) control.view.destroy();
    this.glow.destroy();
    this.root.destroy({ children: true });
  }
}
'use client';
import { useEffect, useRef, useState, type RefObject } from 'react';
import type { AssetPack } from '@/game/assets/asset-pack';
import { MAIN_MENU, type MainMenuMotion } from '@/game/core/main-menu';
import type { StageRuntime } from '@/game/services/stage-runtime';
import type { MainMenuView } from '@/game/render/main-menu-view';
import { BubbleText, Icon } from './ui';

const controls = [
  { name: 'play_btn', label: 'Play', caption: 'PLAY', css: 'play', icon: 'play', size: 78 },
  {
    name: 'settings_btn',
    label: 'Settings',
    caption: 'SETTINGS',
    css: 'settings',
    icon: 'settings',
    size: 21,
  },
  {
    name: 'partsPacks_btn',
    label: 'My tanks',
    caption: 'MY TANKS',
    css: 'library',
    icon: 'plus',
    size: 28,
  },
  {
    name: 'credits_btn',
    label: 'Credits',
    caption: 'CREDITS',
    css: 'credits',
    icon: 'file',
    size: 21,
  },
  {
    name: 'enemyCreator_btn',
    label: 'Enemy tank creator',
    caption: 'CREATE A TANK',
    css: 'create',
    icon: 'library',
    size: 26,
  },
  {
    name: 'pmg_btn',
    label: 'Change assets',
    caption: 'CHANGE ASSETS',
    css: 'assets',
    icon: 'back',
    size: 20,
  },
] as const;

export function MainMenu({
  pack,
  stage,
  motion,
  covered,
  overlayRoot,
  onAction,
}: {
  pack: AssetPack;
  stage: StageRuntime;
  motion: MainMenuMotion;
  covered: boolean;
  overlayRoot: RefObject<HTMLFieldSetElement | null>;
  onAction: (name: (typeof controls)[number]['name']) => void;
}) {
  const root = useRef<HTMLDivElement>(null),
    canvasHost = useRef<HTMLDivElement>(null),
    buttons = useRef<HTMLDivElement>(null),
    title = useRef<HTMLDivElement>(null),
    native = useRef<MainMenuView | null>(null),
    isCovered = useRef(covered);
  const [error, setError] = useState(false);
  useEffect(() => {
    isCovered.current = covered;
  }, [covered]);
  useEffect(() => {
    let cancelled = false,
      dispose: (() => void) | undefined;
    const release = () => {
      const cleanup = dispose;
      dispose = undefined;
      cleanup?.();
    };
    const present = () => {
      if (!root.current || !buttons.current) return;
      root.current.dataset.menuAge = String(motion.age);
      root.current.dataset.menuParked = String(motion.parked);
      root.current.dataset.menuBusy = String(motion.busy);
      root.current.dataset.controlAlpha = String(motion.controlAlpha);
      root.current.dataset.titleAlpha = String(motion.titleAlpha);
      buttons.current.inert = motion.parked || isCovered.current;
      for (const [index, piece] of MAIN_MENU.controls.entries()) {
        const node = buttons.current.children[index] as HTMLElement,
          m = piece.matrix;
        node.style.left = `${(motion.parked ? -100 : m.tx / 20) + piece.bounds.x * m.a}px`;
        node.style.top = `${(motion.parked ? -100 : m.ty / 20) + piece.bounds.y * m.d}px`;
        node.style.opacity = String(Math.max(0, Math.min(1, motion.controlAlpha)));
      }
      if (title.current)
        title.current.style.opacity = String(Math.max(0, Math.min(1, motion.titleAlpha)));
      if (overlayRoot.current) {
        const wasBlocked = overlayRoot.current.disabled;
        overlayRoot.current.disabled = motion.busy;
        overlayRoot.current.dataset.menuBusy = String(motion.busy);
        if (
          wasBlocked &&
          !motion.busy &&
          isCovered.current &&
          !overlayRoot.current.contains(document.activeElement)
        )
          overlayRoot.current.querySelector<HTMLElement>('[role="dialog"]')?.focus();
      }
    };
    async function start() {
      if (pack.mode === 'mock') {
        present();
        dispose = stage.subscribe({ beforeStep: () => motion.advance(), draw: present });
        return;
      }
      const [{ Application }, { MainMenuView }, { SwfTextures }] = await Promise.all([
        import('pixi.js'),
        import('@/game/render/main-menu-view'),
        import('@/game/render/swf-textures'),
      ]);
      if (cancelled) return;
      const app = new Application(),
        textures = new SwfTextures();
      await app.init({
        width: 550,
        height: 450,
        resolution: 2,
        backgroundAlpha: 0,
        antialias: true,
        autoStart: false,
        preference: 'webgl',
        powerPreference: 'low-power',
      });
      if (cancelled) {
        app.destroy({ removeView: true }, { children: true });
        textures.destroy();
        return;
      }
      dispose = () => {
        app.destroy({ removeView: true }, { children: true });
        textures.destroy();
      };
      const view = new MainMenuView(pack, textures);
      native.current = view;
      app.stage.addChild(view.root);
      app.canvas.setAttribute('aria-hidden', 'true');
      canvasHost.current?.appendChild(app.canvas);
      const draw = () => {
        view.update(motion);
        root.current!.dataset.titleFrame = String(view.titleFrame);
        app.render();
        present();
      };
      const unsubscribe = stage.subscribe({ beforeStep: () => motion.advance(), draw });
      dispose = () => {
        unsubscribe();
        native.current = null;
        view.destroy();
        app.destroy({ removeView: true }, { children: true });
        textures.destroy();
      };
      draw();
    }
    void start().catch(() => {
      release();
      if (!cancelled) setError(true);
    });
    return () => {
      cancelled = true;
      release();
    };
  }, [pack, stage, motion, overlayRoot]);
  return (
    <div ref={root} className="main-menu stage-background" data-assets={pack.mode}>
      <div className="menu-guest">
        <span aria-hidden="true">×</span> Playing as Guest
      </div>
      <span className="menu-version">OPEN · 0.1</span>
      {pack.mode === 'mock' ? (
        <>
          <div className="ambient-bubbles" aria-hidden="true">
            <i />
            <i />
            <i />
          </div>
          <div ref={title} className="menu-title">
            <BubbleText pack={pack} size={57}>
              bubble tanks 3
            </BubbleText>
          </div>
        </>
      ) : (
        <div ref={canvasHost} className="main-menu-art" role="img" aria-label="Bubble Tanks 3" />
      )}
      <div ref={buttons} className="main-menu-controls" inert>
        {controls.map((control, index) => {
          const piece = MAIN_MENU.controls[index];
          return (
            <button
              key={control.name}
              className={`menu-orb menu-${control.css}`}
              aria-label={control.label}
              data-menu-control={control.name}
              style={{
                left: -100,
                top: -100,
                opacity: 0,
                width: piece.bounds.width * piece.matrix.a,
                height: piece.bounds.height * piece.matrix.d,
              }}
              onMouseEnter={() => native.current?.hover(control.name, true)}
              onMouseLeave={() => native.current?.hover(control.name, false)}
              onFocus={() => native.current?.hover(control.name, true)}
              onBlur={() => native.current?.hover(control.name, false)}
              onClick={() => onAction(control.name)}
            >
              {pack.mode === 'mock' ? <Icon name={control.icon} size={control.size} /> : null}
              <span className="orb-caption">{control.caption}</span>
            </button>
          );
        })}
      </div>
      <span className="menu-bottom-left">
        {pack.mode === 'swf' ? 'Original assets loaded' : 'Mock asset mode'}
      </span>
      <span className="menu-bottom-right">All progress saved locally</span>
      {error ? <span role="alert">Menu artwork could not start.</span> : null}
    </div>
  );
}
import { StrictMode, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { MainMenu } from '../../src/components/main-menu';
import { SettingsPanel } from '../../src/components/settings-panel';
import { Dialog } from '../../src/components/ui';
import type { AssetPack } from '../../src/game/assets/asset-pack';
import { MainMenuMotion } from '../../src/game/core/main-menu';
import { DEFAULT_SETTINGS } from '../../src/game/core/constants';
import type { Settings } from '../../src/game/core/types';
import { StageRuntime } from '../../src/game/services/stage-runtime';

function MenuFixture({
  pack,
  stage,
  motion,
}: {
  pack: AssetPack;
  stage: StageRuntime;
  motion: MainMenuMotion;
}) {
  const overlayRoot = useRef<HTMLFieldSetElement>(null);
  const [overlay, setOverlay] = useState<'settings' | 'credits' | null>(null);
  const [settings, setSettings] = useState<Settings>({ ...DEFAULT_SETTINGS });
  const close = () => {
    if (motion.back()) setOverlay(null);
  };
  return (
    <>
      <MainMenu
        pack={pack}
        stage={stage}
        motion={motion}
        covered={overlay !== null}
        overlayRoot={overlayRoot}
        onAction={(name) => {
          if ((name === 'settings_btn' || name === 'credits_btn') && motion.open())
            setOverlay(name === 'settings_btn' ? 'settings' : 'credits');
        }}
      />
      <fieldset
        ref={overlayRoot}
        className="main-menu-overlay"
        disabled={motion.busy}
        data-menu-busy={String(motion.busy)}
      >
        {overlay === 'settings' ? (
          <SettingsPanel pack={pack} settings={settings} onChange={setSettings} onClose={close} />
        ) : null}
        {overlay === 'credits' ? (
          <Dialog title="Credits" onClose={close}>
            <div className="credits">Credits transition</div>
            <button onClick={close}>Back</button>
          </Dialog>
        ) : null}
      </fieldset>
    </>
  );
}

/** Production menu component and shared stage, with deterministic external frame controls. */
export function showMainMenuFlow(pack: AssetPack, host: HTMLElement) {
  const stage = new StageRuntime(),
    motion = new MainMenuMotion();
  const root = createRoot(host),
    controls = document.createElement('div');
  controls.id = 'main-menu-flow-controls';
  for (const count of [1, 5, 20, 95, 100]) {
    const button = document.createElement('button');
    button.textContent = `Menu advance ${count} frames`;
    button.onclick = () => {
      for (let i = 0; i < count; i++) stage.advance(20, 50);
    };
    controls.appendChild(button);
  }
  host.before(controls);
  root.render(
    <StrictMode>
      <MenuFixture pack={pack} stage={stage} motion={motion} />
    </StrictMode>,
  );
  return () => {
    root.unmount();
    controls.remove();
  };
}
